import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.C9sp7nFj.js";const p=JSON.parse('{"title":"Personal Vault","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vault.md","filePath":"guide/vault.md","lastUpdated":1778679767000}'),i={name:"guide/vault.md"};function d(s,e,n,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="personal-vault" tabindex="-1">Personal Vault <a class="header-anchor" href="#personal-vault" aria-label="Permalink to &quot;Personal Vault&quot;">​</a></h1><p>The personal vault stores per-user secrets — logins, payment cards, SSH keys, TOTP seeds, and so on — encrypted <strong>end-to-end in the browser</strong>. The pika server never sees the unencrypted contents. Not even an administrator with full database access can read another user&#39;s items.</p><p>This is a different feature from the <em>secrets-by-reference</em> model pika uses for configs. Configs that inherit from external resources (Vault, AWS Secrets Manager, etc.) are visible to anyone with the right token; the personal vault is yours alone.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Where it lives</th></tr></thead><tbody><tr><td>Master password</td><td>In your head — never sent over the wire</td></tr><tr><td>Secret Key</td><td>Generated at Setup; printed on the Emergency Kit; never sent</td></tr><tr><td>Account key</td><td>Derived in-browser from Master Password + Secret Key via Argon2id</td></tr><tr><td>Vault key</td><td>Random 32 bytes; encrypted with account key; only the wrapped form is stored</td></tr><tr><td>Item title, tags, URL hostnames, payload</td><td><code>XChaCha20-Poly1305</code> ciphertext keyed by the vault key</td></tr><tr><td>Item type, favorite/archived flags, timestamps</td><td>Cleartext on the server (used for list filtering and sort)</td></tr></tbody></table><p>The server stores opaque blobs, the KDF parameters, the wrapped vault key, the item type (fixed enum of 10 values), and a few lifecycle flags. Everything content-bearing is opaque.</p><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h2><p>The vault is designed to keep an attacker who steals a full pika database backup — including the encrypted blobs and the KDF salt — out of the encrypted contents. To read the vault they would need to additionally:</p><ol><li>Know (or guess) your master password, <strong>and</strong></li><li>Possess your Secret Key (32 random bytes from the Emergency Kit).</li></ol><p>Brute-forcing Argon2id with the default parameters costs hundreds of milliseconds per guess on commodity hardware; a long master password combined with the Secret Key is well outside any feasible offline attack window.</p><p>What the server admin <strong>can</strong> see:</p><ul><li>The item <em>type</em> (login / card / identity / …) — a fixed 10-value enum used for icons and the type filter.</li><li>Lifecycle flags: <code>favorite</code>, <code>archived</code>, <code>deleted_at</code>, <code>last_used_at</code>, <code>created_at</code>, <code>updated_at</code>.</li><li>Item counts and the version number on each row.</li><li>The audit log of vault operations (when hooks are configured).</li></ul><p>What the server admin <strong>cannot</strong> see:</p><ul><li>Item titles. Encrypted with the per-user vault key before they leave the browser.</li><li>Tags. Same — encrypted as a list before transit.</li><li>URL hostnames. Same. (A future autofill feature will introduce a blind index alongside; today they are fully opaque.)</li><li>Passwords, TOTP seeds, card numbers, SSH private keys, or any other field value.</li><li>The notes attached to an item.</li><li>The master password or Secret Key.</li></ul><h2 id="initial-setup" tabindex="-1">Initial setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial setup&quot;">​</a></h2><ol><li>Navigate to <strong>Vault</strong> in the navbar after logging in.</li><li>Choose a master password (8 characters minimum; longer is much better — 4–5 random words from a wordlist is the recommended baseline).</li><li>Pick a KDF preset: <ul><li><strong>Fast</strong> (32 MiB, 2 iterations) — older devices, mobile.</li><li><strong>Default</strong> (64 MiB, 3 iterations) — modern laptop / desktop.</li><li><strong>Strong</strong> (128 MiB, 4 iterations) — power user / paranoid.</li></ul></li><li>The server generates the Emergency Kit immediately. <strong>Save it now</strong> — the Secret Key is shown exactly once.</li></ol><p>The kit can be printed, downloaded as HTML, or copied to a password-manager-of-last-resort. Anyone with both the kit and your master password can read your vault, so keep them separate (master password in your head; kit in a fireproof safe or a deposit box).</p><h2 id="unlocking-on-another-device" tabindex="-1">Unlocking on another device <a class="header-anchor" href="#unlocking-on-another-device" aria-label="Permalink to &quot;Unlocking on another device&quot;">​</a></h2><p>To unlock the vault on a different browser or after the auto-lock fired:</p><ol><li>Sign in to pika normally (the session is independent of the vault unlock).</li><li>Open <strong>Vault</strong>.</li><li>Enter your master password and Secret Key.</li></ol><p>The Secret Key field accepts dashes, spaces, and either case — the formatting on the printed kit is for readability only.</p><h2 id="item-types" tabindex="-1">Item types <a class="header-anchor" href="#item-types" aria-label="Permalink to &quot;Item types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Default fields</th></tr></thead><tbody><tr><td>Login</td><td>Username, password, website</td></tr><tr><td>Card</td><td>Cardholder, number, expiry, CVV, PIN</td></tr><tr><td>Identity</td><td>Name, email, phone, address</td></tr><tr><td>Secure note</td><td>Just the notes</td></tr><tr><td>SSH key</td><td>Public key, private key, passphrase, fingerprint</td></tr><tr><td>API credential</td><td>Endpoint, API key, API secret</td></tr><tr><td>Database</td><td>Host, port, database, username, password, connection string</td></tr><tr><td>Server</td><td>Hostname, IP, port, username, password</td></tr><tr><td>Software license</td><td>Product, version, license key, support email</td></tr><tr><td>TLS certificate</td><td>Certificate, private key, CA chain, fingerprint, expiry</td></tr></tbody></table><p>You can add, remove, reorder, or change the type of any field on any item — the type list is the starting template, not a constraint.</p><h3 id="totp" tabindex="-1">TOTP <a class="header-anchor" href="#totp" aria-label="Permalink to &quot;TOTP&quot;">​</a></h3><p>Items can hold a TOTP field — either an <code>otpauth://totp/...</code> URL (copied from a QR code) or a bare base32 secret. The 6-digit code is computed in the browser, displayed in the editor with a countdown timer, and copies to clipboard with one click.</p><p>The TOTP feature in the vault is distinct from pika&#39;s <em>own login 2FA</em> — that one is stored under <strong>Settings → Account Security</strong> and gates your pika session. The vault TOTP is for <em>other services</em> (your bank, your GitHub account, your VPN, ...).</p><h2 id="auto-lock" tabindex="-1">Auto-lock <a class="header-anchor" href="#auto-lock" aria-label="Permalink to &quot;Auto-lock&quot;">​</a></h2><p>The vault key lives only in the browser tab&#39;s memory while the vault is unlocked. It is zeroized when:</p><ul><li>You leave the <code>/vault</code> route in the SPA.</li><li>The auto-lock timer fires (default 15 minutes; configurable at Setup time or via the gear menu).</li><li>You explicitly click Lock.</li><li>You log out of pika.</li></ul><p>After a lock, returning to <code>/vault</code> shows the unlock screen again. Active editing is preserved only as long as the tab is alive; refresh = unlock.</p><h2 id="master-password-rotation" tabindex="-1">Master password rotation <a class="header-anchor" href="#master-password-rotation" aria-label="Permalink to &quot;Master password rotation&quot;">​</a></h2><p>Settings → Vault → Change master password runs the full Argon2id re-wrap <strong>locally</strong> with the new password and posts the new wrapped vault key. Items are <strong>not</strong> re-encrypted (the vault key is unchanged); the operation is constant-time regardless of vault size.</p><p>The Secret Key is preserved. To rotate the Secret Key you would need to re-wrap every item, which is a larger surgery — see the Reset path below for now; a proper &quot;rotate Secret Key&quot; flow is planned.</p><h2 id="reset-lost-master-password" tabindex="-1">Reset / lost master password <a class="header-anchor" href="#reset-lost-master-password" aria-label="Permalink to &quot;Reset / lost master password&quot;">​</a></h2><p>If you lose your master password, your vault is unrecoverable. There is no admin reset that preserves the items — that would defeat the threat model. What an admin <strong>can</strong> do is delete the user account, which cascades to wipe the vault entirely.</p><p>A user can also reset their own vault from <strong>Settings → Vault → Delete vault</strong>. This destroys every item irreversibly. You can then run Setup again with a fresh master password and Secret Key.</p><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h2><p>Sharing between users is <strong>not implemented</strong> in this release. Each vault is private to a single user. Cross-user share links with expiry are on the roadmap (Dalga 3).</p><h2 id="hook-events" tabindex="-1">Hook events <a class="header-anchor" href="#hook-events" aria-label="Permalink to &quot;Hook events&quot;">​</a></h2><p>Vault operations emit the following event types (in addition to the existing <code>config.*</code> and <code>file.*</code>):</p><table tabindex="0"><thead><tr><th>Event</th><th>Trigger</th></tr></thead><tbody><tr><td><code>vault.item.created</code></td><td>New item written</td></tr><tr><td><code>vault.item.updated</code></td><td>Existing item updated</td></tr><tr><td><code>vault.item.deleted</code></td><td>Item hard-deleted (purge from trash)</td></tr><tr><td><code>vault.unlock.failed</code></td><td>Bad Secret Key on <code>/me/vault/unlock-check</code></td></tr></tbody></table><p>Events carry the calling user and item id but <strong>never</strong> the encrypted payload. Wire them to a log sink for an audit trail; the server-side state itself is intentionally minimal.</p><h2 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h2><p>All endpoints live under <code>/api/v1/me/vault/*</code> and require an authenticated session — no capability gate, since every user owns their own vault.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/me/vault/status</code></td><td>Lightweight check: initialized? item count?</td></tr><tr><td>GET</td><td><code>/me/vault/account</code></td><td>KDF params + wrapped vault key</td></tr><tr><td>POST</td><td><code>/me/vault/setup</code></td><td>First-time initialization (409 on re-init)</td></tr><tr><td>POST</td><td><code>/me/vault/unlock-check</code></td><td>Rate-limited Secret Key verifier</td></tr><tr><td>POST</td><td><code>/me/vault/rotate-password</code></td><td>Re-wrap the vault key with a new master password</td></tr><tr><td>POST</td><td><code>/me/vault/recovery-kit</code></td><td>Regenerate the kit ID</td></tr><tr><td>PUT</td><td><code>/me/vault/session-lock</code></td><td>Update the auto-lock TTL</td></tr><tr><td>DELETE</td><td><code>/me/vault</code></td><td>Wipe everything (items + history + account)</td></tr><tr><td>GET</td><td><code>/me/vault/items</code></td><td>List items with filter params</td></tr><tr><td>POST</td><td><code>/me/vault/items</code></td><td>Create item</td></tr><tr><td>GET</td><td><code>/me/vault/items/{id}</code></td><td>Get item with encrypted payload</td></tr><tr><td>PUT</td><td><code>/me/vault/items/{id}</code></td><td>Update item (optimistic concurrency on <code>expected_version</code>)</td></tr><tr><td>DELETE</td><td><code>/me/vault/items/{id}</code></td><td>Soft-delete (move to trash); <code>?purge=true</code> for hard-delete</td></tr><tr><td>POST</td><td><code>/me/vault/items-restore/{id}</code></td><td>Restore from trash</td></tr><tr><td>POST</td><td><code>/me/vault/items-use/{id}</code></td><td>Bump <code>last_used_at</code> for &quot;recently used&quot; sorting</td></tr><tr><td>GET</td><td><code>/me/vault/items-versions/{id}</code></td><td>Item edit history (newest first)</td></tr></tbody></table><p>The list filter parameters:</p><table tabindex="0"><thead><tr><th>Param</th><th>Values</th></tr></thead><tbody><tr><td><code>type</code></td><td>One of the known item types (<code>login</code>, <code>card</code>, ...)</td></tr><tr><td><code>favorite</code></td><td><code>1</code> for favorites only</td></tr><tr><td><code>archived</code></td><td><code>include</code> to add archived to the active list; <code>only</code> for archive-only</td></tr><tr><td><code>trash</code></td><td><code>1</code> for trash-only</td></tr></tbody></table><p>There is no <code>q</code> or <code>tag</code> server-side filter — title, tags and URL hostnames are stored as ciphertext. The SPA decrypts the listing in memory and runs free-text + tag filters on the decrypted view. For typical personal vaults (under a few thousand items) the round-trip is sub-second.</p><h3 id="searching-the-vault" tabindex="-1">Searching the vault <a class="header-anchor" href="#searching-the-vault" aria-label="Permalink to &quot;Searching the vault&quot;">​</a></h3><p>After unlock, the SPA fetches the full item list once. Subsequent search keystrokes filter the in-memory decrypted set without hitting the network. Tag chips are populated from the union of every loaded item&#39;s tag list.</p><p>Two consequences:</p><ul><li>Unlock time grows roughly linearly with item count. For 1000 items the title/tags/hostnames decrypt typically runs in ~30 ms on a modern laptop.</li><li>Filtering is not persisted server-side. If you reload the page you lose your search; that&#39;s by design — there&#39;s no way for the server to remember a query against ciphertext anyway.</li></ul><h2 id="what-s-not-in-this-release" tabindex="-1">What&#39;s not in this release <a class="header-anchor" href="#what-s-not-in-this-release" aria-label="Permalink to &quot;What&#39;s not in this release&quot;">​</a></h2><p>These appear in the long-term roadmap but were intentionally deferred:</p><ul><li><strong>Sharing between users</strong> (with expiring links / per-recipient public keys).</li><li><strong>Browser extension and autofill.</strong> A planned blind index on URL hostnames will allow server-side equality matching for the autofill path without leaking the hostname value.</li><li><strong>CLI integration</strong> (<code>pika vault list/get/run -- mycmd</code>).</li><li><strong>Watchtower-style audits</strong> (reused-password detection, HIBP breach lookup, certificate expiry warnings).</li><li><strong>Per-item attachments</strong> (e.g. PDFs scanned alongside a license).</li><li><strong>Passkey PRF unlock</strong> as a master-password alternative on supported authenticators.</li></ul><h2 id="schema-migration-notes" tabindex="-1">Schema migration notes <a class="header-anchor" href="#schema-migration-notes" aria-label="Permalink to &quot;Schema migration notes&quot;">​</a></h2><p>The vault is currently at storage schema <strong>v2</strong>. Earlier development builds used <strong>v1</strong>, which stored item titles, tags and URL hostnames in cleartext on the server.</p><p>When the pika binary boots against an older Badger directory whose vault tables are still at v1, the storage layer detects the version mismatch on first open and wipes all three vault buckets (<code>vault_accounts</code>, <code>vault_items</code>, <code>vault_item_versions</code>) before bw registers them under the v2 schema. A <code>vault: legacy schema detected</code> warning is logged when this happens.</p><p>Because the cleartext-to-ciphertext transition can only be performed client-side (the server doesn&#39;t hold the vault key), no automatic data migration is possible. The personal-vault feature has not yet shipped in a release, so this only affects developer workstations and CI environments — production deployments will start fresh at v2.</p>',60)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
